"use server";

import { prisma } from "@/src/lib/prisma";
import { revalidatePath } from "next/cache";
import { getServerSession } from "next-auth"; 
import { authOptions } from "@/app/api/auth/[...nextauth]/route"; 

interface SessionUser {
  id: string;
  email?: string | null;
  name?: string | null;
}

const GUEST_ID = "guest-uuid-unique-12345";

async function getUserId(): Promise<string | null> {
  const session = await getServerSession(authOptions);
  const user = session?.user as SessionUser | undefined;
  return user?.id || null;
}

/**
 * Misafir kullanıcısının veritabanında var olduğundan emin olur.
 * Eğer yoksa, otomatik olarak oluşturur.
 */
async function ensureUserExists(userId: string) {
  const user = await prisma.user.findUnique({ where: { id: userId } });
  if (!user && userId === GUEST_ID) {
    await prisma.user.create({
      data: {
        id: GUEST_ID,
        email: "guest@proje.com",
        password: "GUEST_PASSWORD_NO_ACCESS", // Bu hesapla manuel giriş yapılamaz
        role: "USER",
      }
    });
  }
}

export async function createCalendarItem(data: {
  id?: string | null;
  titel: string;
  documentType: string;
  datum: string;
  startTime: string;
  endTime: string;
}) {
  try {
    const userId = await getUserId();
    
    if (!userId) {
      return { success: false, error: "Log in om door te gaan." };
    }

    // KRİTİK NOKTA: Kullanıcının (özellikle misafirin) DB'de kayıtlı olduğunu garanti et
    await ensureUserExists(userId);

    const start = new Date(`${data.datum}T${data.startTime}:00`);
    const end = new Date(`${data.datum}T${data.endTime}:00`);

    if (data.id) {
      await prisma.calender.update({
        where: { 
          id: data.id,
          userId: userId 
        },
        data: {
          title: data.titel,
          description: data.documentType,
          startDatetime: start,
          endDatetime: end,
        },
      });
    } else {
      await prisma.calender.create({
        data: {
          userId: userId,
          title: data.titel,
          description: data.documentType,
          startDatetime: start,
          endDatetime: end,
        },
      });
    }

    revalidatePath("/calendar");
    return { success: true };
  } catch (error: unknown) {
    const errorMessage = error instanceof Error ? error.message : "Onbekende fout";
    console.error("Calendar Save Error:", errorMessage);
    return { success: false, error: "Er is bir hata oluştu. Lütfen tekrar deneyin." };
  }
}

export async function deleteCalendarItem(id: string) {
  try {
    const userId = await getUserId();
    if (!userId) return { success: false, error: "Niet geautoriseerd." };

    await prisma.calender.delete({
      where: { 
        id: id,
        userId: userId 
      },
    });

    revalidatePath("/calendar");
    return { success: true };
  } catch (error: unknown) {
    const errorMessage = error instanceof Error ? error.message : "Verwijderen mislukt";
    console.error("Delete Error:", errorMessage);
    return { success: false, error: errorMessage };
  }
}